// The MCP answers JSON-RPC; the payload is a JSON string inside content[0].
const body = $json.body;
if (body?.error) throw new Error(`list_posts: ${body.error.message}`);
const payload = JSON.parse(body.result.content[0].text);
return payload.posts.map((p) => ({ json: p }));

// Only posts that have no hero yet. One image per run keeps the spend
// predictable and means a bad prompt costs one picture, not thirteen.
const body = $json.body;
if (body?.error) throw new Error(`get_post: ${body.error.message}`);
const post = JSON.parse(body.result.content[0].text);
const f = post.frontmatter ?? {};
if (f.heroImage) return [];
if (f.draft) return [];

const pillarScene = {
  'windows-mac': 'a desktop computer and a hard drive, seen from a low angle',
  phones: 'a single handset lying flat, seen from directly above',
  'excel-office': 'a grid of cells and a single highlighted column',
  'ai-tools': 'abstract nodes and connecting lines, loosely arranged',
  'websites-hosting': 'a globe and a server rack, simplified to basic shapes',
  automation: 'interlocking gears and a branching flow line',
};

return [
  {
    json: {
      slug: post.slug,
      title: f.title,
      pillar: f.pillar,
      scene: pillarScene[f.pillar] ?? 'simple geometric shapes',
      alt: `Illustration for ${f.title}`,
    },
  },
];

// gpt-image-1 returns base64. Fail loudly: an empty image that uploads as a
// zero-byte hero is worse than no hero, because the page then looks broken.
const body = $json.body;
const b64 = body?.data?.[0]?.b64_json;
if (!b64) {
  const why = body?.error?.message ?? JSON.stringify(body).slice(0, 300);
  throw new Error(`Image generation returned nothing: ${why}`);
}
if (b64.length < 5000) throw new Error('Image generation returned a suspiciously small file.');
const src = $('Choose a post with no hero').item.json;
return [{ json: { ...src, base64: b64, bytes: Math.round((b64.length * 3) / 4) } }];

// Confirm the hero is actually set, rather than that the call returned 200.
const body = $json.body;
const problems = [];
let out = '';
try {
  out = body.result.content[0].text;
} catch (e) {
  problems.push(`upload_image gave no usable answer: ${JSON.stringify(body).slice(0, 300)}`);
}
if (out && !/heroSet/.test(out)) problems.push(`upload_image did not set a hero: ${out.slice(0, 300)}`);
const src = $('Take the image').item.json;
return [{ json: { slug: src.slug, title: src.title, bytes: src.bytes, problems, count: problems.length } }];
